import{_ as d,o as e,c as a,a2 as o}from"./chunks/framework.Cw6yz976.js";const u=JSON.parse('{"title":"Vesna 内置函数","description":"","frontmatter":{},"headers":[],"relativePath":"guide/builtins.md","filePath":"guide/builtins.md","lastUpdated":1790377022000}'),s={name:"guide/builtins.md"};function n(c,t,r,l,i,p){return e(),a("div",null,[...t[0]||(t[0]=[o(`<h1 id="vesna-内置函数" tabindex="-1">Vesna 内置函数 <a class="header-anchor" href="#vesna-内置函数" aria-label="Permalink to &quot;Vesna 内置函数&quot;">​</a></h1><p><a href="./builtins">English</a> | <a href="./builtins.zh-CN">中文</a></p><p>所有内置函数用 <code>#</code> 前缀，参数用 <code>;</code> 分隔。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#up(&quot;hello&quot;),           /* &quot;HELLO&quot; */</span></span>
<span class="line"><span>#split(&quot;a,b,c&quot;; &quot;,&quot;),   /* [&quot;a&quot;; &quot;b&quot;; &quot;c&quot;] */</span></span></code></pre></div><hr><h2 id="字符串" tabindex="-1">字符串 <a class="header-anchor" href="#字符串" aria-label="Permalink to &quot;字符串&quot;">​</a></h2><table tabindex="0"><thead><tr><th>函数</th><th>说明</th></tr></thead><tbody><tr><td><code>#len(s)</code></td><td>长度</td></tr><tr><td><code>#up(s)</code></td><td>转大写</td></tr><tr><td><code>#down(s)</code></td><td>转小写</td></tr><tr><td><code>#title(s)</code></td><td>每个单词首字母大写</td></tr><tr><td><code>#capitalize(s)</code></td><td>首字母大写，其余小写</td></tr><tr><td><code>#trim(s)</code></td><td>去两边空白</td></tr><tr><td><code>#lstrip(s)</code></td><td>去左空白</td></tr><tr><td><code>#rstrip(s)</code></td><td>去右空白</td></tr><tr><td><code>#sub(s; start; end)</code></td><td>子串，索引从 1 开始</td></tr><tr><td><code>#split(s; sep)</code></td><td>按分隔符切分</td></tr><tr><td><code>#join(list; sep)</code></td><td>拼接列表</td></tr><tr><td><code>#find(s; sub)</code></td><td>查找位置，找不到返回 0</td></tr><tr><td><code>#rfind(s; sub)</code></td><td>从右查找</td></tr><tr><td><code>#replace(s; old; new)</code></td><td>字面替换</td></tr><tr><td><code>#count(s; sub)</code></td><td>子串出现次数</td></tr><tr><td><code>#startswith(s; p)</code></td><td>是否以 p 开头</td></tr><tr><td><code>#endswith(s; p)</code></td><td>是否以 p 结尾</td></tr><tr><td><code>#repeat(s; n)</code></td><td>重复 n 次</td></tr><tr><td><code>#lines(s)</code></td><td>按行切分</td></tr><tr><td><code>#char_at(s; i)</code></td><td>第 i 个字符，从 1 开始</td></tr><tr><td><code>#ord(c)</code></td><td>字符 → 码</td></tr><tr><td><code>#chr(n)</code></td><td>码 → 字符</td></tr></tbody></table><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#sub(&quot;Hello&quot;; &#39;1&#39;; &#39;3&#39;),        /* &quot;He&quot; */</span></span>
<span class="line"><span>#find(&quot;Hello&quot;; &quot;l&quot;),            /* 3 */</span></span>
<span class="line"><span>#replace(&quot;abc&quot;; &quot;b&quot;; &quot;X&quot;),      /* &quot;aXc&quot; */</span></span>
<span class="line"><span>#char_at(&quot;Hello&quot;; &#39;1&#39;),         /* &quot;H&quot; */</span></span>
<span class="line"><span>#ord(&quot;A&quot;),                      /* 65 */</span></span>
<span class="line"><span>#chr(&#39;66&#39;),                     /* &quot;B&quot; */</span></span></code></pre></div><hr><h2 id="类型转换" tabindex="-1">类型转换 <a class="header-anchor" href="#类型转换" aria-label="Permalink to &quot;类型转换&quot;">​</a></h2><table tabindex="0"><thead><tr><th>函数</th><th>说明</th></tr></thead><tbody><tr><td><code>#str(x)</code></td><td>转字符串</td></tr><tr><td><code>#int(x)</code></td><td>转整数</td></tr><tr><td><code>#float(x)</code></td><td>转浮点</td></tr><tr><td><code>#bool(x)</code></td><td>转布尔</td></tr><tr><td><code>#into(type; x)</code></td><td>通用转换</td></tr></tbody></table><p><code>#into</code> 的类型参数是<strong>关键字</strong>，不是字符串：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#into(int; &quot;42&quot;),</span></span>
<span class="line"><span>#into(str; &#39;5&#39;),</span></span>
<span class="line"><span>#into(float; &quot;3.14&quot;),</span></span>
<span class="line"><span>#into(list; &quot;abc&quot;),</span></span></code></pre></div><hr><h2 id="类型判断" tabindex="-1">类型判断 <a class="header-anchor" href="#类型判断" aria-label="Permalink to &quot;类型判断&quot;">​</a></h2><table tabindex="0"><thead><tr><th>函数</th><th>说明</th></tr></thead><tbody><tr><td><code>#type(x)</code></td><td>返回类型名</td></tr><tr><td><code>#is_digit(c)</code></td><td>是否数字字符</td></tr><tr><td><code>#is_alpha(c)</code></td><td>是否字母</td></tr><tr><td><code>#is_alnum(c)</code></td><td>是否字母或数字</td></tr><tr><td><code>#is_space(c)</code></td><td>是否空白</td></tr></tbody></table><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#type(&#39;5&#39;),        /* &quot;int&quot; */</span></span>
<span class="line"><span>#type(&quot;a&quot;),        /* &quot;str&quot; */</span></span>
<span class="line"><span>#type([1; 2]),     /* &quot;list&quot; */</span></span></code></pre></div><hr><h2 id="列表" tabindex="-1">列表 <a class="header-anchor" href="#列表" aria-label="Permalink to &quot;列表&quot;">​</a></h2><table tabindex="0"><thead><tr><th>函数</th><th>说明</th></tr></thead><tbody><tr><td><code>#len(a)</code></td><td>长度</td></tr><tr><td><code>#append(a; x)</code></td><td>追加元素</td></tr><tr><td><code>#pop(a)</code></td><td>弹出末尾</td></tr><tr><td><code>#sort(a)</code></td><td>排序（返回新列表）</td></tr><tr><td><code>#reverse(a)</code></td><td>反转</td></tr><tr><td><code>#slice(a; start; end)</code></td><td>切片</td></tr><tr><td><code>#contains(a; x)</code></td><td>是否包含</td></tr></tbody></table><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>a = [&#39;3&#39;; &#39;1&#39;; &#39;2&#39;],</span></span>
<span class="line"><span>#sort(a),              /* [&#39;1&#39;; &#39;2&#39;; &#39;3&#39;] */</span></span>
<span class="line"><span>#contains(a; &#39;2&#39;),     /* true */</span></span></code></pre></div><hr><h2 id="字典" tabindex="-1">字典 <a class="header-anchor" href="#字典" aria-label="Permalink to &quot;字典&quot;">​</a></h2><table tabindex="0"><thead><tr><th>函数</th><th>说明</th></tr></thead><tbody><tr><td><code>#len(d)</code></td><td>键的数量</td></tr><tr><td><code>#keys(d)</code></td><td>键列表</td></tr><tr><td><code>#values(d)</code></td><td>值列表</td></tr><tr><td><code>#has_key(d; k)</code></td><td>是否包含键</td></tr></tbody></table><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>d = {&quot;a&quot;: &#39;1&#39;; &quot;b&quot;: &#39;2&#39;},</span></span>
<span class="line"><span>#keys(d),              /* [&quot;a&quot;; &quot;b&quot;] */</span></span>
<span class="line"><span>#has_key(d; &quot;a&quot;),      /* true */</span></span></code></pre></div><hr><h2 id="数学" tabindex="-1">数学 <a class="header-anchor" href="#数学" aria-label="Permalink to &quot;数学&quot;">​</a></h2><table tabindex="0"><thead><tr><th>函数</th><th>说明</th></tr></thead><tbody><tr><td><code>#min(a)</code></td><td>最小</td></tr><tr><td><code>#max(a)</code></td><td>最大</td></tr><tr><td><code>#sum(a)</code></td><td>求和</td></tr><tr><td><code>#abs(x)</code></td><td>绝对值</td></tr><tr><td><code>#round(x; n)</code></td><td>四舍五入，保留 n 位</td></tr><tr><td><code>#pow(a; b)</code></td><td>幂</td></tr></tbody></table><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#min([3; 1; 4]),       /* 1 */</span></span>
<span class="line"><span>#max([3; 1; 4]),       /* 4 */</span></span>
<span class="line"><span>#sum([3; 1; 4]),       /* 8 */</span></span>
<span class="line"><span>#abs(&#39;-5&#39;),            /* 5 */</span></span>
<span class="line"><span>#round(&#39;3.14159&#39;; &#39;2&#39;),/* 3.14 */</span></span>
<span class="line"><span>#pow(&#39;2&#39;; &#39;10&#39;),       /* 1024 */</span></span></code></pre></div><hr><h2 id="正则" tabindex="-1">正则 <a class="header-anchor" href="#正则" aria-label="Permalink to &quot;正则&quot;">​</a></h2><table tabindex="0"><thead><tr><th>函数</th><th>说明</th></tr></thead><tbody><tr><td><code>#match(s; pat)</code></td><td>是否匹配</td></tr><tr><td><code>#findall(s; pat)</code></td><td>提取所有匹配</td></tr><tr><td><code>#gsub(s; pat; repl)</code></td><td>替换</td></tr><tr><td><code>#search(s; pat)</code></td><td>搜索，返回分组</td></tr></tbody></table><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#match(&quot;2026-09-12&quot;; &quot;\\\\d{4}&quot;),       /* true */</span></span>
<span class="line"><span>#findall(&quot;a1 b2 c3&quot;; &quot;[a-z]&quot;),        /* [&quot;a&quot;; &quot;b&quot;; &quot;c&quot;] */</span></span>
<span class="line"><span>#gsub(&quot;a1b2&quot;; &quot;[0-9]&quot;; &quot;&quot;),           /* &quot;ab&quot; */</span></span></code></pre></div><hr><h2 id="文件与目录" tabindex="-1">文件与目录 <a class="header-anchor" href="#文件与目录" aria-label="Permalink to &quot;文件与目录&quot;">​</a></h2><table tabindex="0"><thead><tr><th>函数</th><th>说明</th></tr></thead><tbody><tr><td><code>#fread(path)</code></td><td>读文件</td></tr><tr><td><code>#fwrite(path; text)</code></td><td>写文件</td></tr><tr><td><code>#fappend(path; text)</code></td><td>追加</td></tr><tr><td><code>#fexists(path)</code></td><td>文件是否存在</td></tr><tr><td><code>#ls(dir)</code></td><td>列目录</td></tr><tr><td><code>#glob(pat)</code></td><td>通配匹配</td></tr><tr><td><code>#rmdir(path)</code></td><td>递归删除目录（不存在时忽略）</td></tr></tbody></table><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#fread(&quot;data.txt&quot;),</span></span>
<span class="line"><span>#fwrite(&quot;out.txt&quot;; &quot;hello\\n&quot;),</span></span>
<span class="line"><span>#fappend(&quot;log.txt&quot;; &quot;new line\\n&quot;),</span></span>
<span class="line"><span>#fexists(&quot;data.txt&quot;),       /* true */</span></span>
<span class="line"><span>#ls(&quot;.&quot;),                   /* 文件列表 */</span></span>
<span class="line"><span>#glob(&quot;*.ves&quot;),             /* 所有 .ves 文件 */</span></span></code></pre></div><hr><h2 id="系统" tabindex="-1">系统 <a class="header-anchor" href="#系统" aria-label="Permalink to &quot;系统&quot;">​</a></h2><table tabindex="0"><thead><tr><th>函数</th><th>说明</th></tr></thead><tbody><tr><td><code>#args()</code></td><td>命令行参数列表</td></tr><tr><td><code>#stdin()</code></td><td>读标准输入</td></tr><tr><td><code>#exit(code)</code></td><td>退出程序</td></tr><tr><td><code>#setenv(name; value)</code></td><td>设置用户环境变量（HKCU\\Environment）</td></tr><tr><td><code>#getenv(name)</code></td><td>读取进程环境变量</td></tr><tr><td><code>#regenv(name)</code></td><td>读取用户环境变量（HKCU\\Environment）</td></tr><tr><td><code>#regwrite(root; path; name; value)</code></td><td>写注册表值（root: HKLM / HKCU）</td></tr><tr><td><code>#regdelete(root; path)</code></td><td>删除注册表键树（递归）</td></tr><tr><td><code>#shell(cmd)</code></td><td>运行 shell 命令</td></tr><tr><td><code>#path_clean(p)</code></td><td>规范化路径</td></tr><tr><td><code>#cwd()</code></td><td>当前工作目录</td></tr><tr><td><code>#cpdir(src; dst)</code></td><td>递归复制目录</td></tr></tbody></table><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>args = #args(),</span></span>
<span class="line"><span>path = args[&#39;1&#39;],</span></span></code></pre></div><hr><h2 id="函数式" tabindex="-1">函数式 <a class="header-anchor" href="#函数式" aria-label="Permalink to &quot;函数式&quot;">​</a></h2><table tabindex="0"><thead><tr><th>函数</th><th>说明</th></tr></thead><tbody><tr><td><code>#map(list; &quot;fn&quot;)</code></td><td>对每个元素调用 fn</td></tr><tr><td><code>#filter(list; &quot;fn&quot;)</code></td><td>保留 fn 返回真的元素</td></tr><tr><td><code>#reduce(list; &quot;fn&quot;; init)</code></td><td>归约</td></tr></tbody></table><p><strong>函数名用字符串</strong>：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>def is_error(line)-</span></span>
<span class="line"><span>-back(#match(line; &quot;ERROR&quot;))</span></span>
<span class="line"><span></span></span>
<span class="line"><span>errors = #filter(lines; &quot;is_error&quot;),</span></span></code></pre></div><p><code>#map</code> 和 <code>#filter</code> 的 <code>fn</code> 接受一个参数。<code>#reduce</code> 接受两个参数：累加器和当前元素。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>def add(a; b)-</span></span>
<span class="line"><span>-back(a + b)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>total = #reduce(nums; &quot;add&quot;; &#39;0&#39;),</span></span></code></pre></div><hr><h2 id="插值字符串" tabindex="-1">插值字符串 <a class="header-anchor" href="#插值字符串" aria-label="Permalink to &quot;插值字符串&quot;">​</a></h2><p><code>#f&quot;...&quot;</code> 把字符串里的 <code>(var)</code> 替换为变量值：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>name = &quot;Vesna&quot;,</span></span>
<span class="line"><span>age = &#39;1&#39;,</span></span>
<span class="line"><span>print(#f&quot;name=(name), age=(age)&quot;),</span></span>
<span class="line"><span>/* 输出：name=Vesna, age=1 */</span></span></code></pre></div><p><code>(name)</code> 里只能是变量名，不能是表达式。</p><hr><hr><h2 id="_0-4-通用语言扩充" tabindex="-1">0.4 通用语言扩充 <a class="header-anchor" href="#_0-4-通用语言扩充" aria-label="Permalink to &quot;0.4 通用语言扩充&quot;">​</a></h2><p>1.0.0 新增。<code>#rand</code>、<code>#randint</code>、<code>#choice</code>、<code>#shuffle</code>、<code>#now</code>、<code>#date</code>、<code>#sleep</code>、<code>#ticks</code>、<code>#platform</code>、<code>#temp_dir</code> 为非确定性或依赖环境；其余均为确定性函数。</p><h3 id="进阶数学" tabindex="-1">进阶数学 <a class="header-anchor" href="#进阶数学" aria-label="Permalink to &quot;进阶数学&quot;">​</a></h3><table tabindex="0"><thead><tr><th>函数</th><th>说明</th></tr></thead><tbody><tr><td><code>#sqrt(x)</code></td><td>平方根</td></tr><tr><td><code>#floor(x)</code> / <code>#ceil(x)</code></td><td>向下 / 向上取整</td></tr><tr><td><code>#exp(x)</code></td><td>e 的 x 次方</td></tr><tr><td><code>#log(x)</code> / <code>#log10(x)</code></td><td>自然 / 常用对数（x &gt; 0）</td></tr><tr><td><code>#sin(x)</code> / <code>#cos(x)</code> / <code>#tan(x)</code></td><td>三角函数（弧度）</td></tr><tr><td><code>#sign(x)</code></td><td>-1 / 0 / 1</td></tr><tr><td><code>#clamp(x; lo; hi)</code></td><td>夹取到 [lo; hi]</td></tr><tr><td><code>#rand()</code></td><td>[0; 1) 随机浮点数</td></tr><tr><td><code>#randint(a; b)</code></td><td>[a; b] 随机整数</td></tr><tr><td><code>#choice(a)</code></td><td>列表随机取一个元素</td></tr><tr><td><code>#shuffle(a)</code></td><td>返回打乱后的副本</td></tr></tbody></table><h3 id="进制" tabindex="-1">进制 <a class="header-anchor" href="#进制" aria-label="Permalink to &quot;进制&quot;">​</a></h3><table tabindex="0"><thead><tr><th>函数</th><th>说明</th></tr></thead><tbody><tr><td><code>#hex(n)</code></td><td>转十六进制（无前缀、小写）</td></tr><tr><td><code>#bin(n)</code></td><td>转二进制</td></tr><tr><td><code>#oct(n)</code></td><td>转八进制</td></tr></tbody></table><h3 id="字符串-1" tabindex="-1">字符串 <a class="header-anchor" href="#字符串-1" aria-label="Permalink to &quot;字符串&quot;">​</a></h3><table tabindex="0"><thead><tr><th>函数</th><th>说明</th></tr></thead><tbody><tr><td><code>#pad(s; w; c)</code></td><td>用 c 将 s 居中补齐到宽度 w</td></tr><tr><td><code>#lpad(s; w; c)</code></td><td>右对齐（左侧补齐）</td></tr><tr><td><code>#rpad(s; w; c)</code></td><td>左对齐（右侧补齐）</td></tr><tr><td><code>#format(fmt; ...)</code></td><td>C 风格格式化：<code>%s</code> <code>%d</code> <code>%f</code> <code>%.2f</code> <code>%%</code></td></tr><tr><td><code>#hash(s)</code></td><td>确定性 FNV-1a 64 位哈希（十进制字符串）</td></tr></tbody></table><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#format(&quot;%s-%d-%.2f&quot;; &quot;v&quot;; &#39;42&#39;; &#39;3.14159&#39;),  /* &quot;v-42-3.14&quot; */</span></span>
<span class="line"><span>#hash(&quot;hello&quot;),                               /* 确定性 64 位数字 */</span></span>
<span class="line"><span>#lpad(&quot;ab&quot;; &#39;5&#39;; &quot;0&quot;),                        /* &quot;000ab&quot; */</span></span></code></pre></div><h3 id="列表-1" tabindex="-1">列表 <a class="header-anchor" href="#列表-1" aria-label="Permalink to &quot;列表&quot;">​</a></h3><table tabindex="0"><thead><tr><th>函数</th><th>说明</th></tr></thead><tbody><tr><td><code>#range(start; end; step)</code></td><td>整数序列 <code>[start; end)</code></td></tr><tr><td><code>#first(a)</code> / <code>#last(a)</code></td><td>首 / 尾元素（空则 none）</td></tr><tr><td><code>#take(a; n)</code> / <code>#drop(a; n)</code></td><td>保留 / 去掉前 n 个</td></tr><tr><td><code>#set(a)</code></td><td>去重（保序）</td></tr><tr><td><code>#flatten(a)</code></td><td>展开一层</td></tr><tr><td><code>#zip(a; b)</code></td><td>两两配对为组</td></tr><tr><td><code>#insert(a; i; x)</code></td><td>在 1 起始位置 i 插入 x，返回新列表</td></tr><tr><td><code>#remove(a; i)</code></td><td>删除 1 起始第 i 个元素，返回新列表</td></tr><tr><td><code>#index_of(a; x)</code></td><td>1 起始位置，找不到为 0</td></tr><tr><td><code>#enumerate(a)</code></td><td><code>[(i; v); ...]</code>，索引从 1 起</td></tr><tr><td><code>#concat(a; b)</code></td><td>拼接两个列表</td></tr></tbody></table><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#range(&#39;1&#39;; &#39;5&#39;),          /* [&#39;1&#39;;&#39;2&#39;;&#39;3&#39;;&#39;4&#39;] */</span></span>
<span class="line"><span>#zip([&#39;1&#39;;&#39;2&#39;]; [&quot;a&quot;;&quot;b&quot;]),/* [(&#39;1&#39;;a);(&#39;2&#39;;b)] */</span></span>
<span class="line"><span>#set([&#39;1&#39;;&#39;1&#39;;&#39;2&#39;]),       /* [&#39;1&#39;;&#39;2&#39;] */</span></span></code></pre></div><h3 id="字典-1" tabindex="-1">字典 <a class="header-anchor" href="#字典-1" aria-label="Permalink to &quot;字典&quot;">​</a></h3><table tabindex="0"><thead><tr><th>函数</th><th>说明</th></tr></thead><tbody><tr><td><code>#get(d; k; default)</code></td><td>取键值，缺失返回 default（默认 none）</td></tr><tr><td><code>#items(d)</code></td><td><code>[(k; v); ...]</code></td></tr><tr><td><code>#pop_key(d; k)</code></td><td>删除键并返回旧值（无则 none）</td></tr></tbody></table><h3 id="类型判断-1" tabindex="-1">类型判断 <a class="header-anchor" href="#类型判断-1" aria-label="Permalink to &quot;类型判断&quot;">​</a></h3><p><code>#is_str</code> <code>#is_int</code> <code>#is_float</code> <code>#is_bool</code> <code>#is_list</code> <code>#is_dict</code> <code>#is_none</code> <code>#is_group</code></p><h3 id="时间-系统" tabindex="-1">时间 / 系统 <a class="header-anchor" href="#时间-系统" aria-label="Permalink to &quot;时间 / 系统&quot;">​</a></h3><table tabindex="0"><thead><tr><th>函数</th><th>说明</th></tr></thead><tbody><tr><td><code>#now()</code></td><td>Unix 时间戳（int）</td></tr><tr><td><code>#date(fmt)</code></td><td>本地时间格式化（默认 <code>%Y-%m-%d %H:%M:%S</code>）</td></tr><tr><td><code>#date_format(ts; fmt)</code></td><td>格式化任意时间戳（默认 <code>%Y-%m-%d %H:%M:%S</code>）</td></tr><tr><td><code>#parse_time(s; fmt)</code></td><td>把格式化字符串解析为时间戳（支持 <code>%Y %m %d %H %M %S</code>）</td></tr><tr><td><code>#sleep(ms)</code></td><td>睡眠毫秒</td></tr><tr><td><code>#ticks()</code></td><td>自启动起单调毫秒数</td></tr><tr><td><code>#platform()</code></td><td><code>&quot;windows&quot;</code> / <code>&quot;linux&quot;</code> / <code>&quot;mac&quot;</code></td></tr><tr><td><code>#arch()</code></td><td><code>&quot;x64&quot;</code> / <code>&quot;arm64&quot;</code> / <code>&quot;x86&quot;</code> / <code>&quot;unknown&quot;</code></td></tr><tr><td><code>#temp_dir()</code></td><td>系统临时目录</td></tr><tr><td><code>#uuid()</code></td><td>随机 UUID v4 字符串（36 字符）</td></tr></tbody></table><h3 id="文件" tabindex="-1">文件 <a class="header-anchor" href="#文件" aria-label="Permalink to &quot;文件&quot;">​</a></h3><table tabindex="0"><thead><tr><th>函数</th><th>说明</th></tr></thead><tbody><tr><td><code>#fremove(path)</code></td><td>删除文件（不存在不报错）</td></tr><tr><td><code>#fmove(src; dst)</code></td><td>移动文件</td></tr><tr><td><code>#fsize(path)</code></td><td>文件字节数</td></tr><tr><td><code>#file_time(path)</code></td><td>文件最后修改时间（unix 秒）</td></tr><tr><td><code>#truncate(path; size)</code></td><td>将文件截断 / 扩展为 <code>size</code> 字节</td></tr><tr><td><code>#is_dir(path)</code> / <code>#is_file(path)</code></td><td>路径类型判断</td></tr><tr><td><code>#mkdirs(path)</code></td><td>递归创建目录</td></tr></tbody></table><h3 id="编码" tabindex="-1">编码 <a class="header-anchor" href="#编码" aria-label="Permalink to &quot;编码&quot;">​</a></h3><table tabindex="0"><thead><tr><th>函数</th><th>说明</th></tr></thead><tbody><tr><td><code>#base64_encode(s)</code> / <code>#base64_decode(s)</code></td><td>base64 编解码</td></tr><tr><td><code>#url_encode(s)</code> / <code>#url_decode(s)</code></td><td>URL 百分号编码（空格 → <code>+</code>）</td></tr></tbody></table><h3 id="函数式-1" tabindex="-1">函数式 <a class="header-anchor" href="#函数式-1" aria-label="Permalink to &quot;函数式&quot;">​</a></h3><table tabindex="0"><thead><tr><th>函数</th><th>说明</th></tr></thead><tbody><tr><td><code>#each(list; &quot;fn&quot;)</code></td><td>对每个元素执行副作用，返回原列表</td></tr><tr><td><code>#all(list; &quot;fn&quot;)</code></td><td>全部为真？</td></tr><tr><td><code>#any(list; &quot;fn&quot;)</code></td><td>任一为真？</td></tr><tr><td><code>#find_first(list; &quot;fn&quot;)</code></td><td>第一个为真的元素（无则 none）</td></tr><tr><td><code>#sort_by(list; &quot;fn&quot;)</code></td><td>按 fn 键稳定排序</td></tr></tbody></table><h3 id="异常" tabindex="-1">异常 <a class="header-anchor" href="#异常" aria-label="Permalink to &quot;异常&quot;">​</a></h3><table tabindex="0"><thead><tr><th>函数</th><th>说明</th></tr></thead><tbody><tr><td><code>#throw(msg)</code></td><td>抛出错误</td></tr><tr><td><code>#assert(cond; msg)</code></td><td>条件为假则抛出</td></tr></tbody></table><h2 id="_1-1-并发-网络-二进制" tabindex="-1">1.1 并发 / 网络 / 二进制 <a class="header-anchor" href="#_1-1-并发-网络-二进制" aria-label="Permalink to &quot;1.1 并发 / 网络 / 二进制&quot;">​</a></h2><h3 id="并发" tabindex="-1">并发 <a class="header-anchor" href="#并发" aria-label="Permalink to &quot;并发&quot;">​</a></h3><table tabindex="0"><thead><tr><th>函数</th><th>说明</th></tr></thead><tbody><tr><td><code>#thread(&quot;fn&quot;; arg...)</code></td><td>在新线程中运行 <code>fn</code>（全局变量按副本隔离），返回线程 id（int）</td></tr><tr><td><code>#thread_join(id)</code></td><td>等待线程结束并返回其 <code>back</code> 值；线程出错则重新抛出</td></tr><tr><td><code>#thread_count()</code></td><td>当前仍在运行（未 join）的线程数</td></tr><tr><td><code>#lock(&quot;name&quot;)</code></td><td>获取命名互斥锁（阻塞），首次使用自动创建</td></tr><tr><td><code>#unlock(&quot;name&quot;)</code></td><td>释放命名互斥锁；未锁定过则报错</td></tr></tbody></table><p>说明：每个线程在独立的全局变量副本上运行（函数定义共享且只读）。共享文件 / 共享资源写入请用 <code>#lock</code>/<code>#unlock</code> 保护；<code>print</code> 输出已互斥。已 join 的线程会从表中移除；未 join 的线程在解释器退出时自动等待。</p><h3 id="网络-需系统-path-中有-curl" tabindex="-1">网络（需系统 PATH 中有 curl） <a class="header-anchor" href="#网络-需系统-path-中有-curl" aria-label="Permalink to &quot;网络（需系统 PATH 中有 curl）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>函数</th><th>说明</th></tr></thead><tbody><tr><td><code>#http_get(url)</code></td><td>GET 请求，返回响应体字符串</td></tr><tr><td><code>#http_post(url; body)</code></td><td>POST 表单请求，返回响应体字符串</td></tr><tr><td><code>#tcp_ping(host; port)</code></td><td>TCP 连通返回 <code>0</code>，拒绝/超时返回 <code>1</code>，错误返回 <code>-1</code></td></tr><tr><td><code>#http_server(port; &quot;handler&quot;)</code></td><td>阻塞式 HTTP 服务；每请求调用 <code>handler(req)</code>，<code>req</code> 为 <code>{method; path; headers; body}</code>；handler 返回字符串（200）或 <code>{code; body; type}</code></td></tr></tbody></table><h3 id="二进制" tabindex="-1">二进制 <a class="header-anchor" href="#二进制" aria-label="Permalink to &quot;二进制&quot;">​</a></h3><table tabindex="0"><thead><tr><th>函数</th><th>说明</th></tr></thead><tbody><tr><td><code>#bin_read(path)</code></td><td>以字节列表（0-255 整数）读取文件</td></tr><tr><td><code>#bin_write(path; bytes)</code></td><td>将字节列表（每项 0-255）写入文件</td></tr><tr><td><code>#bin_hex(bytes)</code></td><td>字节 → 小写十六进制字符串</td></tr><tr><td><code>#bin_unhex(s)</code></td><td>十六进制字符串 → 字节列表（长度须为偶数）</td></tr><tr><td><code>#bin_base64_encode(bytes)</code></td><td>字节 → base64 字符串</td></tr><tr><td><code>#bin_base64_decode(s)</code></td><td>base64 字符串 → 字节列表</td></tr></tbody></table><p>字节就是普通整数，现有列表操作（<code>#len</code>、<code>#slice</code>、<code>#append</code> 等）可直接用于二进制数据。</p><h2 id="_1-2-数据-加密-进程-ffi" tabindex="-1">1.2 数据 / 加密 / 进程 / FFI <a class="header-anchor" href="#_1-2-数据-加密-进程-ffi" aria-label="Permalink to &quot;1.2 数据 / 加密 / 进程 / FFI&quot;">​</a></h2><h3 id="数据" tabindex="-1">数据 <a class="header-anchor" href="#数据" aria-label="Permalink to &quot;数据&quot;">​</a></h3><table tabindex="0"><thead><tr><th>函数</th><th>说明</th></tr></thead><tbody><tr><td><code>#json_encode(v)</code></td><td>将任意值序列化为 JSON 字符串（dict 保持插入顺序）</td></tr><tr><td><code>#json_decode(s)</code></td><td>解析 JSON 为 dict / list / int / float / string / bool / none；非法输入报错</td></tr><tr><td><code>#re_groups(s; pattern)</code></td><td>返回首个正则匹配的捕获组列表：组 0 为整段匹配，未匹配组为 <code>none</code>；无匹配返回空列表</td></tr></tbody></table><h3 id="加密" tabindex="-1">加密 <a class="header-anchor" href="#加密" aria-label="Permalink to &quot;加密&quot;">​</a></h3><table tabindex="0"><thead><tr><th>函数</th><th>说明</th></tr></thead><tbody><tr><td><code>#sha256(s)</code></td><td>SHA-256 十六进制摘要（64 字符），已按 FIPS 180-4 向量验证；1.8.0 起也接受字节列表（<code>#sha256(#bin_read(path))</code> 做真实文件哈希）</td></tr><tr><td><code>#aes_encrypt(data; key)</code></td><td>AES-256-CBC + PKCS7，密钥经 SHA-256 派生，返回 base64（已按 FIPS-197 验证）</td></tr><tr><td><code>#aes_decrypt(b64; key)</code></td><td>用相同密钥解密 <code>#aes_encrypt</code> 产生的 base64 密文</td></tr></tbody></table><p>说明：AES 采用固定全零 IV 与 SHA-256 派生密钥——适合本地工具与静态数据加密，不作为高安全通道中认证加密的替代。</p><h3 id="进程" tabindex="-1">进程 <a class="header-anchor" href="#进程" aria-label="Permalink to &quot;进程&quot;">​</a></h3><table tabindex="0"><thead><tr><th>函数</th><th>说明</th></tr></thead><tbody><tr><td><code>#proc_run(cmd)</code></td><td>运行命令，返回 dict <code>{&quot;exit&quot;: 退出码; &quot;output&quot;: 捕获的 stdout}</code></td></tr></tbody></table><h3 id="ffi-windows-x64-linux-macos-经-dlopen" tabindex="-1">FFI（Windows x64；Linux/macOS 经 dlopen） <a class="header-anchor" href="#ffi-windows-x64-linux-macos-经-dlopen" aria-label="Permalink to &quot;FFI（Windows x64；Linux/macOS 经 dlopen）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>函数</th><th>说明</th></tr></thead><tbody><tr><td><code>#ffi_call(&quot;dll&quot;; &quot;func&quot;; arg...)</code></td><td>加载共享库并调用 C 函数；参数支持 int / 字符串（字符串以 <code>char*</code> 传入），最多 6 个；返回 64 位整数结果</td></tr></tbody></table><p>示例：<code>#ffi_call(&quot;kernel32.dll&quot;; &quot;GetTickCount&quot;)</code>、<code>#ffi_call(&quot;kernel32.dll&quot;; &quot;GetModuleHandleA&quot;; &quot;kernel32.dll&quot;)</code>。</p><h2 id="_1-9-网络-文件加解密" tabindex="-1">1.9 网络 / 文件加解密 <a class="header-anchor" href="#_1-9-网络-文件加解密" aria-label="Permalink to &quot;1.9 网络 / 文件加解密&quot;">​</a></h2><h3 id="tcp-套接字-原生" tabindex="-1">TCP 套接字（原生） <a class="header-anchor" href="#tcp-套接字-原生" aria-label="Permalink to &quot;TCP 套接字（原生）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>函数</th><th>说明</th></tr></thead><tbody><tr><td><code>#tcp_connect(host; port)</code></td><td>连接 TCP 服务器，返回套接字句柄（整数）</td></tr><tr><td><code>#tcp_listen(port)</code></td><td>在端口上 bind + listen，返回监听句柄（整数）</td></tr><tr><td><code>#tcp_accept(srv)</code></td><td>在监听句柄上阻塞接受连接，返回客户端句柄（整数）</td></tr><tr><td><code>#tcp_send(sock; data)</code></td><td>把字符串完整发送到套接字，返回已发送字节数（整数）</td></tr><tr><td><code>#tcp_recv(sock; maxlen)</code></td><td>接收至多 <code>maxlen</code> 字节并以字符串返回；对端关闭时返回空串</td></tr><tr><td><code>#tcp_close(sock)</code></td><td>关闭套接字</td></tr></tbody></table><p>回显服务示例：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>srv = #tcp_listen(&#39;9000&#39;),</span></span>
<span class="line"><span>cli = #tcp_accept(srv),</span></span>
<span class="line"><span>msg = #tcp_recv(cli; &#39;4096&#39;),</span></span>
<span class="line"><span>#tcp_send(cli; &quot;echo: &quot; + msg),</span></span>
<span class="line"><span>#tcp_close(cli),</span></span>
<span class="line"><span>#tcp_close(srv),</span></span></code></pre></div><p>句柄就是普通整数，可存进列表/字典，也可跨 <code>#thread</code> 线程传递。</p><h3 id="文件-文件夹加解密-aes-256-cbc-原地操作" tabindex="-1">文件 / 文件夹加解密（AES-256-CBC，原地操作） <a class="header-anchor" href="#文件-文件夹加解密-aes-256-cbc-原地操作" aria-label="Permalink to &quot;文件 / 文件夹加解密（AES-256-CBC，原地操作）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>函数</th><th>说明</th></tr></thead><tbody><tr><td><code>#encrypt_file(path; key)</code></td><td>原地加密文件；内容替换为 base64 密文；返回 <code>true</code></td></tr><tr><td><code>#decrypt_file(path; key)</code></td><td>还原 <code>#encrypt_file</code> 加密的文件；密钥错误或非 Vesna 密文会报错；返回 <code>true</code></td></tr><tr><td><code>#encrypt_dir(dir; key)</code></td><td>递归原地加密目录下所有文件，返回处理文件数</td></tr><tr><td><code>#decrypt_dir(dir; key)</code></td><td>递归还原 <code>#encrypt_dir</code> 加密的文件，返回还原文件数</td></tr></tbody></table><p>说明：密钥经 SHA-256 派生（与 <code>#aes_encrypt</code> 一致）；密文带 <code>VSENC1</code> 魔数前缀，错误密钥解密会被识别。操作为原地覆盖——批量执行前如需可先备份。</p><h2 id="完整例子" tabindex="-1">完整例子 <a class="header-anchor" href="#完整例子" aria-label="Permalink to &quot;完整例子&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>import json,</span></span>
<span class="line"><span></span></span>
<span class="line"><span>args = #args(),</span></span>
<span class="line"><span>path = args[&#39;1&#39;],</span></span>
<span class="line"><span></span></span>
<span class="line"><span>if not #fexists(path)-</span></span>
<span class="line"><span>-print(&quot;找不到文件: &quot; + path),</span></span>
<span class="line"><span>-#exit(&#39;1&#39;),</span></span>
<span class="line"><span></span></span>
<span class="line"><span>content = #fread(path),</span></span>
<span class="line"><span>lines = #lines(content),</span></span>
<span class="line"><span></span></span>
<span class="line"><span>def is_error(line)-</span></span>
<span class="line"><span>-back(#match(line; &quot;ERROR&quot;))</span></span>
<span class="line"><span></span></span>
<span class="line"><span>errors = #filter(lines; &quot;is_error&quot;),</span></span>
<span class="line"><span></span></span>
<span class="line"><span>result = {</span></span>
<span class="line"><span>    &quot;file&quot;: path;</span></span>
<span class="line"><span>    &quot;total&quot;: #len(lines);</span></span>
<span class="line"><span>    &quot;errors&quot;: #len(errors)</span></span>
<span class="line"><span>},</span></span>
<span class="line"><span></span></span>
<span class="line"><span>print(json_write(result)),</span></span></code></pre></div>`,112)])])}const b=d(s,[["render",n]]);export{u as __pageData,b as default};
